function effectValue(entity,kind){return(entity?.effects??[]).filter(effect=>effect.kind===kind&&effect.turns>0).reduce((best,effect)=>Math.max(best,Number(effect.value)||0),0)}
function statFactor(entity,up,down){return Math.max(.2,1+effectValue(entity,up)-effectValue(entity,down))}
function tickEffects(entity){if(!entity)return;entity.effects=(entity.effects??[]).map(effect=>({...effect,turns:effect.turns-1})).filter(effect=>effect.turns>0)}
function addEffect(entity,effect){if(!entity||!effect)return;entity.effects??=[];const current=entity.effects.find(entry=>entry.kind===effect.kind);if(current){current.value=Math.max(current.value,effect.value);current.turns=Math.max(current.turns,effect.turns)}else entity.effects.push({...effect})}
function circleDamageFactor(actor,round=1,aliveCount=2){const effect=actor?.circleEffect??"none",level=Math.max(0,Number(actor?.circleLevel)||0),missing=1-actor.hp/Math.max(1,actor.maxHp);if(effect==="openingBuff")return 1.2;if(effect==="manaReversal")return 1.15+Math.min(.25,level*.004);if(effect==="rage")return 1+missing*.75;if(effect==="lowHpPower")return 1+missing*1.15;if(effect==="goldPower")return 1.12+Math.min(.3,level*.004);if(effect==="soleSurvivor"&&aliveCount===1)return 1.65;if(effect==="slot"){const roll=Math.abs(hashText(`${actor.playerId}:${round}`))%1000;if(roll===0)return 0;return .5+roll/400}return 1}
