function sanitizeHostWorld(source={}){const result={openedChestIds:{},defeatedBossFloors:[],claimedBossRewardFloors:[]};const opened=source?.openedChestIds&&typeof source.openedChestIds==="object"?source.openedChestIds:{};for(const[floor,ids]of Object.entries(opened).slice(0,10_000)){const key=String(integer(floor,1,MAX_FLOOR,1));result.openedChestIds[key]=[...new Set((Array.isArray(ids)?ids:[]).map(value=>text(value,80)).filter(Boolean).slice(0,200))]}result.defeatedBossFloors=[...new Set((Array.isArray(source?.defeatedBossFloors)?source.defeatedBossFloors:[]).map(value=>integer(value,1,MAX_FLOOR,1)).filter(value=>value%10===0))].slice(0,1000);result.claimedBossRewardFloors=[...new Set((Array.isArray(source?.claimedBossRewardFloors)?source.claimedBossRewardFloors:[]).map(value=>integer(value,1,MAX_FLOOR,1)).filter(value=>value%10===0))].slice(0,1000);return result}

